document.addEventListener("DOMContentLoaded",initHeaderCart);function initHeaderCart(){const header=document.querySelector("header.site-header");if(!header||document.getElementById("header-cart-link"))return;const host=header.querySelector(".header-top-row")||header.querySelector(".container");if(!host)return;const link=document.createElement("a");link.id="header-cart-link";link.className="header-cart";link.href="my-carts.html";link.setAttribute("aria-label","Your carts");link.innerHTML='<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+'<circle cx="9" cy="21" r="1"></circle><circle cx="20" cy="21" r="1"></circle>'+'<path d="M1 1h4l2.68 13.39a2 2 0 0 0 2 1.61h9.72a2 2 0 0 0 2-1.61L23 6H6"></path></svg>'+'<span class="header-cart-badge" id="header-cart-badge" hidden></span>';host.appendChild(link);updateHeaderCartBadge()}function updateHeaderCartBadge(){const badge=document.getElementById("header-cart-badge");if(!badge)return;const total=totalCartItemCount();if(total>0){badge.textContent=total>99?"99+":String(total);badge.hidden=false}else{badge.hidden=true}}